insert into public.incubators (name, description, focus_area, location, remote, application_url, logo_url, curator_verified) values
('Co-Creation Hub (CcHub)', 'Nigeria''s first innovation hub, offering a 6-month pre-incubation program with $5,000 funding, 12-month incubation with $25,000, and a 12-week accelerator offering up to $250,000.', 'Tech, social impact', 'Lagos, Abuja', false, 'https://cchubnigeria.com', 'https://logo.clearbit.com/cchubnigeria.com', true),
